#!/usr/bin/env python3
"""Script to examine Excel file structure"""
import openpyxl
import sys

def examine_workbook(filename):
    wb = openpyxl.load_workbook(filename, data_only=False)
    print(f"\nWorkbook: {filename}")
    print(f"Sheets: {wb.sheetnames}\n")

    for sheet_name in wb.sheetnames:
        ws = wb[sheet_name]
        print(f"\n{'='*60}")
        print(f"Sheet: {sheet_name}")
        print(f"{'='*60}")
        print(f"Dimensions: {ws.dimensions}")

        # Print first 30 rows and up to column P
        print("\nData preview:")
        for row_idx, row in enumerate(ws.iter_rows(min_row=1, max_row=50, max_col=16), 1):
            row_data = []
            for cell in row:
                if cell.value is not None:
                    # Show formula if present
                    if isinstance(cell.value, str) and cell.value.startswith('='):
                        row_data.append(f"[{cell.column_letter}{cell.row}:{cell.value[:50]}...]" if len(cell.value) > 50 else f"[{cell.column_letter}{cell.row}:{cell.value}]")
                    else:
                        row_data.append(f"{cell.column_letter}{cell.row}:{cell.value}")
            if row_data:
                print(f"  Row {row_idx}: {', '.join(row_data)}")

if __name__ == "__main__":
    filename = sys.argv[1] if len(sys.argv) > 1 else "/root/test - demand.xlsx"
    examine_workbook(filename)

