#!/usr/bin/env python3
"""Fetch IMF WEO data for Georgia"""
import requests
import json

# Try IMF JSON API
base_url = "https://www.imf.org/external/datamapper/api/v1"

# Indicators we need:
# NGDP - Gross domestic product, current prices (National currency)
# NGDPD - Gross domestic product, current prices (U.S. dollars)
# NGDP_RPCH - Gross domestic product, constant prices (Percent change)
# NGDP_D - Gross domestic product, deflator (Index)

indicators = ["NGDP", "NGDPD", "NGDP_RPCH", "NGDP_D"]

print("Fetching WEO data for Georgia (GEO)...")

for indicator in indicators:
    try:
        url = f"{base_url}/{indicator}"
        print(f"\nFetching {indicator}...")
        response = requests.get(url, timeout=10)

        if response.status_code == 200:
            data = response.json()
            if 'values' in data and indicator in data['values']:
                if 'GEO' in data['values'][indicator]:
                    print(f"\n{indicator} data for Georgia:")
                    geo_data = data['values'][indicator]['GEO']
                    # Sort by year
                    sorted_years = sorted(geo_data.keys())
                    for year in sorted_years:
                        if 2020 <= int(year) <= 2027:
                            print(f"  {year}: {geo_data[year]}")
                else:
                    print(f"  No data found for Georgia")
            else:
                print(f"  Unexpected data structure")
        else:
            print(f"  HTTP {response.status_code}")
    except Exception as e:
        print(f"  Error: {e}")

