#!/usr/bin/env python3
"""Fetch additional IMF WEO data for Georgia"""
import requests

# Try different API endpoints
endpoints = [
    "https://www.imf.org/external/datamapper/api/v1/NGDP",
    "https://www.imf.org/external/datamapper/api/v1/NGDP_D",
    "https://www.imf.org/external/datamapper/api/v1/PCPIPCH",  # Inflation
]

for endpoint in endpoints:
    try:
        print(f"\nFetching from {endpoint}...")
        response = requests.get(endpoint, timeout=10)
        if response.status_code == 200:
            data = response.json()
            print(f"Keys in response: {list(data.keys())[:5]}")

            # Try to find Georgia data
            if 'values' in data:
                for key in data['values']:
                    if 'GEO' in data['values'][key]:
                        print(f"\nFound GEO data for {key}:")
                        geo_data = data['values'][key]['GEO']
                        sorted_years = sorted([y for y in geo_data.keys() if y.isdigit()])
                        for year in sorted_years:
                            if 2020 <= int(year) <= 2027:
                                print(f"  {year}: {geo_data[year]}")
                        break
    except Exception as e:
        print(f"Error: {e}")

# Calculate deflator from nominal GDP and real GDP data
print("\n" + "="*60)
print("CALCULATING GDP DEFLATOR FROM NOMINAL/REAL GDP")
print("="*60)

# Data we have:
ngdpd = {2020: 16.013, 2021: 18.849, 2022: 24.985, 2023: 30.778, 2024: 33.775, 2025: 37.403, 2026: 40.177, 2027: 42.408}
real_growth = {2020: -6.3, 2021: 10.6, 2022: 11, 2023: 7.8, 2024: 9.4, 2025: 7.2, 2026: 5.3, 2027: 5}

# Use exchange rate 2.746 GEL/USD as specified
exchange_rate = 2.746

print("\nNominal GDP in GEL (using exchange rate 2.746):")
ngdp_gel = {}
for year, value_usd in ngdpd.items():
    ngdp_gel[year] = value_usd * exchange_rate
    print(f"  {year}: {ngdp_gel[year]:.3f} billion GEL")

# Calculate real GDP index (base 2019 = 100)
print("\nCalculating Real GDP Index (2019=100):")
real_gdp_index = {2019: 100.0}
for year in sorted(real_growth.keys()):
    if year > 2019:
        prev_year = year - 1
        prev_index = real_gdp_index.get(prev_year, real_gdp_index[2019])
        real_gdp_index[year] = prev_index * (1 + real_growth[year]/100)
        print(f"  {year}: {real_gdp_index[year]:.3f}")

# Calculate deflator (Nominal GDP / Real GDP * 100)
# We need 2019 nominal GDP as base
# Estimate 2019 GDP using backward calculation
ngdp_2019_est = ngdp_gel[2020] / (1 + (-6.3 + 0)/100)  # Rough estimate
print(f"\nEstimated 2019 Nominal GDP: {ngdp_2019_est:.3f} billion GEL")

print("\nGDP Deflator (2019=100):")
for year in sorted(ngdp_gel.keys()):
    if year in real_gdp_index:
        deflator = (ngdp_gel[year] / ngdp_2019_est) / (real_gdp_index[year] / 100) * 100
        print(f"  {year}: {deflator:.2f}")

